// Extract and validate incoming property data
const body = $input.first().json.body;

if (!body.imageUrl || !body.address || !body.requestId) {
  throw new Error('Missing required fields: imageUrl, address, requestId');
}

const { street, city, state, zip } = body.address;
if (!street || !city || !state || !zip) {
  throw new Error('Incomplete address information');
}

// Format address for API calls
const fullAddress = `${street}, ${city}, ${state} ${zip}`;
const searchAddress = `${street} ${city} ${state} ${zip}`.replace(/,/g, '');

return {
  json: {
    imageUrl: body.imageUrl,
    address: {
      street,
      city,
      state,
      zip,
      full: fullAddress,
      search: searchAddress
    },
    requestId: body.requestId,
    userId: body.userId || 'system',
    timestamp: new Date().toISOString()
  }
};

