// Merge all data sources for comprehensive analysis
const items = $input.all();

// Find each data source
const propertyData = items.find(item => item.json.address)?.json;
const zillowProperty = items.find(item => item.json.results || item.json.properties)?.json;
const zillowComps = items.find(item => item.json.sales || item.json.sold_properties)?.json;
const zillowTrends = items.find(item => item.json.market_data || item.json.trends)?.json;
const zillowRentals = items.find(item => item.json.rentals || item.json.rental_data)?.json;
const geminiAnalysis = items.find(item => item.json.candidates)?.json;

// Parse Gemini response
let geminiData = {};
try {
  if (geminiAnalysis?.candidates?.[0]?.content?.parts?.[0]?.text) {
    const geminiText = geminiAnalysis.candidates[0].content.parts[0].text;
    // Extract JSON from Gemini response
    const jsonMatch = geminiText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      geminiData = JSON.parse(jsonMatch[0]);
    }
  }
} catch (error) {
  console.log('Error parsing Gemini response:', error);
  geminiData = { error: 'Failed to parse Gemini analysis' };
}

return {
  json: {
    requestId: propertyData?.requestId || 'unknown',
    propertyInfo: propertyData,
    zillowProperty: zillowProperty || {},
    zillowComparables: zillowComps || {},
    zillowMarketTrends: zillowTrends || {},
    zillowRentals: zillowRentals || {},
    geminiAnalysis: geminiData,
    processingTimestamp: new Date().toISOString()
  }
};

