// Format final response for QuicklyClose integration
const mergedData = $input.first().json;
const geminiResponse = mergedData.candidates?.[0]?.content?.parts?.[0]?.text;

// Parse Gemini's final analysis
let finalAnalysis = {};
try {
  if (geminiResponse) {
    const jsonMatch = geminiResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      finalAnalysis = JSON.parse(jsonMatch[0]);
    }
  }
} catch (error) {
  console.log('Error parsing final Gemini analysis:', error);
  // Fallback structure
  finalAnalysis = {
    features: [],
    estimatedValue: 0,
    confidence: 0,
    flipComps: {},
    rentalComps: {},
    similarProperties: []
  };
}

// Ensure all required fields exist with defaults
const response = {
  features: finalAnalysis.features || [],
  estimatedValue: finalAnalysis.estimatedValue || 0,
  confidence: finalAnalysis.confidence || 0,
  flipComps: {
    after_repair_value: finalAnalysis.flipComps?.after_repair_value || 0,
    price_per_sqft: finalAnalysis.flipComps?.price_per_sqft || 0,
    days_on_market: finalAnalysis.flipComps?.days_on_market || 0,
    sale_to_list_ratio: finalAnalysis.flipComps?.sale_to_list_ratio || 0.98,
    renovation_grade: finalAnalysis.flipComps?.renovation_grade || 'Unknown',
    recent_sales: [],
    lot_size: 0.25,
    zoning_potential: 'Residential',
    neighborhood_trends: finalAnalysis.flipComps?.neighborhood_trends || 'Stable',
    property_type_match: 'Single Family Home'
  },
  rentalComps: {
    market_rent_estimate: finalAnalysis.rentalComps?.market_rent_estimate || 0,
    rent_to_price_ratio: finalAnalysis.rentalComps?.rent_to_price_ratio || 0,
    cap_rate: finalAnalysis.rentalComps?.cap_rate || 0,
    vacancy_rate: finalAnalysis.rentalComps?.vacancy_rate || 5.0,
    tenant_turnover: 'Average',
    crime_rate: 'Average',
    school_district_quality: finalAnalysis.rentalComps?.school_district_quality || 'Good',
    transit_employment_access: 'Good',
    hoa_fees: 0,
    property_taxes: finalAnalysis.rentalComps?.property_taxes || 0
  },
  similarProperties: finalAnalysis.similarProperties || []
};

return {
  json: response
};
